  const publicRoutes = new Set(['home','catalog','contact','login','privacy','terms']);
  async function api(path, opts = {}) {
    const headers = {'Accept':'application/json',...(opts.body ? {'Content-Type':'application/json'} : {}),...(S.csrf ? {'X-CSRF-Token':S.csrf} : {}),...(opts.idempotent ? {'Idempotency-Key':opts.idempotent} : {})};
    let response;
    try { response = await fetch(path,{method:opts.method || 'GET',headers,credentials:'same-origin',cache:'no-store',...(opts.body ? {body:JSON.stringify(opts.body)} : {})}); }
    catch { throw new Error('The server could not be reached. Check your connection and try again.'); }
    let body; try { body = await response.json(); } catch { throw new Error('The server returned an unexpected response. Please try again.'); }
    if (!response.ok) { const error = new Error(body.error || 'This request could not be completed.'); error.status=response.status; error.code=body.code; throw error; }
    return body;
  }
  async function refresh() { S.data=await api('/api/bootstrap');S.user=S.data.user;S.csrf=S.data.csrf || S.csrf;if(!members().some(m=>m.id===S.focus))S.focus=self()?.id || members()[0]?.id || null; }
