  function brand() { return `<span class="pg-brand" aria-label="Dhanvantri Global Pvt Ltd"><img src="assets/dhanvantri-mark.png" alt="" width="48" height="48"><span>DHANVANTRI<small>GLOBAL PVT LTD</small></span></span>`; }
