  function publicFooter() {return `<footer class="pg-footer"><div>${brand()}<p>Products and a connected partner experience.</p></div><div><h3>DISCOVER</h3><a href="#home">About the company</a><a href="#catalog">Products</a><a href="#contact">Contact & enquiries</a></div><div><h3>PARTNER WORKSPACE</h3><a href="#overview">Dashboard</a><a href="#team">Binary tree</a><a href="#income">Income reports</a></div><div><h3>INFORMATION</h3><a href="#terms">Website terms</a><a href="#privacy">Privacy policy</a><p>Income depends on approved qualifying sales and the company’s approved plan. No income is guaranteed.</p></div><div class="pg-copyright">© ${new Date().getFullYear()} ${COMPANY}</div></footer>`;}
  function dropdown(label,entries) {return `<details class="pg-nav-dropdown"><summary>${label}</summary><div>${entries.map(([name,route])=>`<a href="#${route}">${name}</a>`).join('')}</div></details>`;}
  function memberHeader() {return `<header class="pg-member-header"><a href="#overview" aria-label="${COMPANY} dashboard">${brand()}</a><button class="pg-menu" data-pg="menu" aria-label="Toggle member navigation">☰</button><nav id="pg-member-nav">${dropdown('DIRECT SELLER DETAIL',[['PROFILE DETAIL','profile'],['ACCOUNT SECURITY','security']])}${dropdown('REGISTRATION & PURCHASING',[...(admin()?[['NEW REGISTRATION','admin-members']]:[]),['PURCHASE ORDER','catalog'],['PURCHASE WALLET','funding']])}${dropdown('SALE DETAILS',[['ORDER DETAIL','orders'],['INCOME REFLECTION','reflection']])}${dropdown('GENEALOGY',[['BINARY TREE','team'],['TEAM MEMBER REPORT','members']])}${dropdown('COMMISSION REPORTS',[['INCOME REPORT','income'],['CLOSING STATEMENT','statement'],['PAYOUT DETAILS','wallet']])}<a href="#benefits">REWARD & BENEFITS</a>${admin()?dropdown('MANAGEMENT',[['ADMIN CONSOLE','admin'],['MEMBERS','admin-members'],['PRODUCTS','admin-products'],['INVENTORY & STOCK','admin-inventory'],['ORDER REVIEW','admin-orders'],['PROFIT & CLOSING','admin-closing'],['HYBRID & REWARD INCENTIVES','admin-incentives'],['WALLET REVIEW','admin-funding'],['PAYOUT REVIEW','admin-withdrawals'],['BENEFIT REVIEW','admin-benefits'],['PLAN CONFIGURATION','admin-plan'],['ENQUIRIES','admin-enquiries'],['AUDIT HISTORY','audit']]):''}<button data-pg="logout">LOGOUT</button></nav></header>`;}
  function metrics(member) {return member||{left_bv:0,right_bv:0,carry_left_bv:0,carry_right_bv:0,self_bv:0,matched_bv:0};}
