  function tileIcon(kind) {const mapped=({member:'profile',product:'profile',wallet:'money',team:'team',report:'document',benefit:'award',security:'kyc',audit:'document',logout:'logout'})[kind]||'document';return window.PartnerReference?.art?`<span class="pg-tile-symbol" aria-hidden="true">${window.PartnerReference.art(mapped)}</span>`:`<span class="pg-tile-symbol" aria-hidden="true">◇</span>`;}
