  const filteredLedger=()=> (S.data.ledger||[]).filter(r=>(S.route==='reflection'||r.account==='commission')&&(S.route!=='statement'||r.kind==='matching_credit')&&(S.ledgerType==='all'||r.type===S.ledgerType||r.kind===S.ledgerType)&&(!S.ledgerMonth||String(r.created_at||r.date||'').startsWith(S.ledgerMonth))&&(!admin()||S.ledgerMember==='all'||r.member_id===S.ledgerMember));
