  function resetPrivateResources() {S.statements=null;S.inventory=null;S.incentives=null;S.incentiveSeq++;S.importRows=null;S.importVerified=false;S.query='';S.ledgerMember='all';S.ledgerMonth='';S.statementSeq++;S.inventorySeq++;S.statementFilters={member_id:'',period:'',from:'',to:'',page:1,page_size:25};}
