  function reviewButtons(type,r) {if(type==='orders'&&r.status==='Approved')return orderActions(r);if(/rejected|paid|approved|reviewed|cancelled/i.test(r.status)&&!(type==='withdrawals'&&/^approved$/i.test(r.status)))return '—';return `<div class="pg-row-actions">${type==='withdrawals'&&/^approved$/i.test(r.status)?button('Record transfer','review-form',`data-type="${type}" data-id="${esc(r.id)}" data-decision="paid"`):button('Approve','review-form',`data-type="${type}" data-id="${esc(r.id)}" data-decision="approve"`)}${button('Reject','review-form',`data-type="${type}" data-id="${esc(r.id)}" data-decision="reject"`,'light')}</div>`;}
  function adminReview(type) {const rows=type==='funding'?S.data.fundingRequests:type==='withdrawals'?S.data.withdrawals:type==='benefits'?S.data.benefits:S.data.orders;const desc={orders:'Approval verifies the order and records business volume once. Rejected orders return reserved purchase funds.',funding:'Verify the external payment before approving wallet credit. This interface does not process a bank payment.',withdrawals:'Approve a reserved request after review. Record “Paid” only after an external transfer has completed.',benefits:'Review eligibility using company records. Education approval records review only and does not disburse a loan.'}[type];return pageTitle(heading[S.route],desc)+panel('Company review queue',table(['Reference','Member','Created','Request','Status','Action'],(rows||[]).map(r=>[esc(r.id),esc(r.member_id),date(r.created_at),type==='orders'?`${esc(r.product_name||r.product_id)} × ${num(r.quantity)}<br>${money(r.total_paise||r.amount_paise)}`:type==='benefits'?`${esc(r.type)} · ${esc(r.period)}<br>${esc(r.note)}`:`${money(r.amount_paise)}<br>${esc(r.reference||'')}`,type==='orders'?badge(orderDisplayStatus(r))+'<br>'+fulfilmentCell(r):badge(r.status),reviewButtons(type,r)])));}
  function plan() {const p=S.data.plan||{};return pageTitle('Plan configuration','The 50% member / 50% company allocation is fixed. Activate only with the company’s approved written plan.')+`<div class="pg-form-column">${panel('Approved plan settings',`<form data-form="plan">${field('Business volume per matching pair','pair_bv','number',p.pair_bv||'','required min="1" step="1"')}${field('Income per matching pair (INR)','pair_income','number',p.pair_income_paise/100||'','required min="0.01" step="0.01"')}${field('Maximum pairs per closing per member','max_pairs_per_closing','number',p.max_pairs_per_closing||'','required min="1" step="1"')}${field('Written plan approval reference','approval_reference','text',p.approval_reference||'','required maxlength="200"')}<label class="pg-check"><input type="checkbox" name="approved" ${p.approved?'checked':''}> The company has approved this compensation plan for operation.</label><p class="pg-form-error" role="alert"></p><button class="pg-button">Save approved settings</button></form>`)}</div>`;}
  function closing() {const s=S.data.summary||{},p=S.data.plan||{};return pageTitle('Profit & matching closing','Only verified realised profit funds the member pool. Closing is computed and settled on the server once.')+note()+`<div class="pg-small-stats">${stat('MEMBER POOL REMAINING',money(s.member_pool_remaining_paise),'blue','admin-closing')}${stat('MEMBER / COMPANY SHARE','50% / 50%','orange','admin-plan')}</div><div class="pg-two-column">${panel('Record realised profit',`<form data-form="profit">${field('Verified realised profit (INR)','amount','number','','required min="0.01" step="0.01"')}${field('Accounting / verification reference','reference','text','','required maxlength="200"')}<p class="pg-form-note">Do not enter sales revenue as profit. This record allocates 50% of the verified amount to the member pool.</p><p class="pg-form-error" role="alert"></p><button class="pg-button" ${!p.approved?'disabled':''}>Record verified profit</button></form>`)}${panel('Run matching closing',`<p>Approved qualifying sales, remaining carry and the configured pair rate determine credits. The server rejects a closing that cannot be funded.</p><dl class="pg-details"><div><dt>Pair volume</dt><dd>${num(p.pair_bv)} BV</dd></div><div><dt>Pair income</dt><dd>${money(p.pair_income_paise)}</dd></div><div><dt>Pair cap</dt><dd>${num(p.max_pairs_per_closing)}</dd></div></dl><form data-form="closing"><input type="hidden" name="idempotency_key" value="${reqid()}"><p class="pg-form-error" role="alert"></p><button class="pg-button" ${!p.approved?'disabled':''}>Run funded matching closing</button></form>`)}</div>`;}
  function enquiries() {return pageTitle('Customer enquiries','Private enquiry information is available only to administrators.')+panel('Enquiries',table(['Reference','Created','Contact','Message','Status','Action'],(S.data.enquiries||[]).map(r=>[esc(r.id),date(r.created_at),`${esc(r.name)}<br>${esc(r.email)}<br>${esc(r.phone||'')}`,esc(r.message),badge(r.status),button(r.status==='Resolved'?'Reopen':'Resolve','enquiry-status',`data-id="${esc(r.id)}" data-status="${r.status==='Resolved'?'Open':'Resolved'}"`,'light')])));}
